// ================================================================
//            PROVIDED TEST HARNESS -- DO NOT EDIT THIS FILE
// ================================================================
// Tests binom from binom.s.
//
// Input: one query "n k" per line, 0 <= n <= 30, 0 <= k <= 30. Prints binom(n, k).
// If the first line is the word check, it also prints an ERROR line for
// every callee-saved register (rbx, rbp, r12-r15, rsp) that binom changed.
#include <stdio.h>
#include <string.h>

unsigned long call_binom(unsigned long n, unsigned long k, unsigned long *changed);

int main(void) {
    static const char *names[] = {"rbx", "rbp", "r12", "r13", "r14", "r15", "rsp"};
    char line[128];
    int check = 0, first = 1;
    while (fgets(line, sizeof line, stdin)) {
        if (first && strncmp(line, "check", 5) == 0) { check = 1; first = 0; continue; }
        first = 0;
        unsigned long n, k, changed;
        if (sscanf(line, "%lu %lu", &n, &k) != 2 || n > 30 || k > 30) continue;
        unsigned long r = call_binom(n, k, &changed);
        printf("binom(%lu, %lu) = %lu\n", n, k, r);
        if (check)
            for (int i = 0; i < 7; i++)
                if (changed >> i & 1) printf("ERROR: callee-saved register %s was not preserved\n", names[i]);
    }
    return 0;
}
